#!/usr/bin/env bash
# llm-launcher defaults. Do not edit this file.
# Personal settings belong in config/config.local.sh (gitignored),
# or use `llm config set <KEY> <VALUE>`.

CONFIG_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
LLM_HOME="$(cd "$CONFIG_DIR/.." && pwd)"

# User overrides (created by setup.sh / llm config set)
if [[ -f "$CONFIG_DIR/config.local.sh" ]]; then
    # shellcheck source=/dev/null
    source "$CONFIG_DIR/config.local.sh"
fi

# Derived defaults (only applied when not overridden)
: "${LLAMA_HOME:=$LLM_HOME/llama.cpp}"
: "${LLAMA_BIN:=$LLAMA_HOME/build/bin/llama-cli}"

: "${MODEL_DIR:=$LLM_HOME/models}"

: "${DEFAULT_MODEL:=}"

: "${MEMORY_DIR:=$LLM_HOME/memory}"
: "${MEMORY_FILE:=$MEMORY_DIR/memory.md}"

: "${CONTEXT_SIZE:=16384}"
: "${NGL:=99}"

: "${DEVICE:=}"
: "${MEMORY_ENABLED:=false}"

# Allow MEMORY_FILE to be stored as a bare filename.
if [[ -n "${MEMORY_FILE:-}" && "$MEMORY_FILE" != /* ]]; then
    MEMORY_FILE="$MEMORY_DIR/$MEMORY_FILE"
fi
